package com.yourname.yellowduck.cleopatra;
import net.minecraft.core.BlockPos;import net.minecraft.world.entity.*;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.Blocks;import java.util.*;
public class CleopatraSnakeSummoner extends Entity {private int timer;private boolean p,f,i;private List<BlockPos> pads;public CleopatraSnakeSummoner(EntityType<?> t,Level l){super(t,l);}@Override protected void defineSynchedData(){}@Override public boolean isPickable(){return false;}@Override public void tick(){super.tick();if(level().isClientSide)return;timer++;if(pads==null)pads=findPads();if(timer>=60&&!p){p=true;spawn(0,CleopatraEntities.SNAKE_POISON.get());}if(timer>=120&&!f){f=true;spawn(1,CleopatraEntities.SNAKE_FIRE.get());}if(timer>=180&&!i){i=true;spawn(2,CleopatraEntities.SNAKE_ICE.get());}if(timer>=200)discard();}
private List<BlockPos> findPads(){List<BlockPos> out=new ArrayList<>();for(int x=-29;x<=30;x++)for(int z=-29;z<=30;z++){BlockPos best=null;for(int y=100;y<=140;y++){BlockPos q=new BlockPos(x,y,z);if(level().getBlockState(q).is(Blocks.AMETHYST_BLOCK))best=q;}if(best!=null)out.add(best);}out.sort(Comparator.comparingInt((BlockPos pos) -> pos.getX()).thenComparingInt(pos -> pos.getZ()));return out.size()>3?new ArrayList<>(out.subList(0,3)):out;}
private void spawn(int idx,EntityType<CleopatraVenomSnake> type){CleopatraVenomSnake s=type.create(level());if(s==null)return;double x,z,y;if(pads!=null&&idx<pads.size()){BlockPos q=pads.get(idx);x=q.getX()+.5;y=q.getY()+1;z=q.getZ()+.5;}else{double yaw=Math.toRadians(getYRot()),forward=9,side=idx==0?0:(idx==1?-8:8);x=getX()-Math.sin(yaw)*forward+Math.cos(yaw)*side;z=getZ()+Math.cos(yaw)*forward+Math.sin(yaw)*side;y=getY();}s.moveTo(x,y,z,getYRot(),0);level().addFreshEntity(s);}
@Override protected void addAdditionalSaveData(net.minecraft.nbt.CompoundTag t){t.putInt("SummonTimer",timer);t.putBoolean("PoisonSpawned",p);t.putBoolean("FireSpawned",f);t.putBoolean("IceSpawned",i);}@Override protected void readAdditionalSaveData(net.minecraft.nbt.CompoundTag t){timer=t.getInt("SummonTimer");p=t.getBoolean("PoisonSpawned");f=t.getBoolean("FireSpawned");i=t.getBoolean("IceSpawned");}}
